ANNOTATIONS = [
    (1, 'before', '''底部状态栏。用户在 settings 里配一条 shell 命令（例如自己写个 `~/.claude/statusline.sh`），Claude Code 就把当前会话的一整套快照喂给它、把它的 stdout 原样显示在输入框下方。所以这份文件有两个重心：**快照结构**（定义了插件能拿到什么，等于一个对外契约）与**刷新时机**（极其克制的防抖与依赖判断，因为每次刷新都要起一个子进程）。'''),
    (30, 'before', '''是否显示状态栏只有一个判据——settings 里配了 statusLine。唯一的例外是 KAIROS（助手模式）：那种模式下本进程只是个 REPL/守护壳，模型、权限模式、cwd 全是壳的、不是子代理真实跑的东西，显示出来会误导，所以直接隐藏。'''),
    (36, 'before', '''这个函数是整份文件里唯一的「对外契约」：它把散落在各处的运行时状态拼成一个纯数据对象交给子进程。注意它**不读 React 状态**，所有入参都由调用方传进来——这样它可以被单独测试，也避免了在函数内部踩到 hook 规则。'''),
    (51, 'before', '''rate_limits 用两层条件展开构造：外层只在真有五小时/七天任一窗口时才加整个字段，内层各自展开。这样最终对象里**不存在值为 undefined 的键**——因为 JSON 序列化会把 undefined 键整个丢掉，而下游脚本可能用 `「five_hour」 in data` 判断，键在但值空会导致误判。'''),
    (65, 'before', '''返回值一律用 `...(cond && { ... })` 展开，同理：可选段在不需要时**不存在**，而不是存在且为空。这份结构里有七个可选段（session_name / rate_limits / vim / agent / remote / worktree），全部遵守同一约定。'''),
    (102, 'before', '''vim 段只在用户开了 vim 模式时才出现，且 `mode` 兜底到 INSERT。这个兜底有实际意义：模式状态在输入框卸载的瞬间可能是 undefined，对脚本来说 undefined 不如 INSERT 有用。'''),
    (117, 'before', '''worktree 段把五个字段全给：名字、路径、分支、原始 cwd、原始分支。这是全份结构里最「厚」的一段，因为 worktree 会话下用户最常搞混的就是「我现在到底在哪个目录、哪个分支、相对哪个基线」——状态栏是唯一能常驻提示的地方。'''),
    (128, 'before', '''messages 走 ref、只有 lastAssistantMessageId 是真正的重渲染触发源。这两个字段是配套的：ref 保证回调里能读到最新消息列表，id 保证「消息没变就不重渲染」。若把 messages 直接当 prop，每来一条流式片段都会重渲染一次状态栏。'''),
    (143, 'before', '''组件内部有六个 ref 加两个「历史状态」ref，看着很重，但分工明确：`abortControllerRef` 管取消、`debounceTimerRef` 管防抖、`logNextResultRef` 管「这次要不要打日志」、`previousStateRef` 管「哪些输入真的变了」。这是「回调要稳定、但要用最新值」的标准解法——把最新值塞进 ref，回调依赖数组就能保持为空。'''),
    (152, 'before', '''这段注释记录了一个真实修过的 bug（issue 37596）：模型名必须从 AppState 取，不能调 `getMainLoopModel()`。后者每次都重读 settings.json，于是**另一个会话里执行 /model** 写盘之后，本会话的状态栏会跟着变——明明这个会话没换模型。凡是「显示当前会话状态」的地方，都不能读全局可变配置。'''),
    (158, 'before', '''五个 ref 在每次渲染时**直接赋值**（不是放 effect 里）。这是有意的：渲染期同步赋值能保证在任何事件回调（防抖到期、子进程返回）里读到的都是本次渲染的值；放 effect 里会晚一帧，状态栏就会显示上一轮的模型或权限模式。'''),
    (170, 'before', '''previousStateRef 专门记「上一次真正用于计算的输入」。注意它初始化时就带着当前值（permissionMode / vimMode / mainLoopModel），这样挂载后的第一次 effect 不会因为「初始值不等于 undefined」而误触发一次多余刷新。'''),
    (191, 'before', '''doUpdate 是唯一真正干活的地方，依赖数组只有 `[messagesRef, setAppState]`，两个都是稳定引用——所以这个回调**永不重建**。这是它被 setTimeout 记住、被各处调用的前提。'''),
    (203, 'before', '''`doesMostRecentAssistantMessageExceed200k` 只在**最后一条助手消息的 id 变了**时才重算。这个函数要遍历消息、累加 token，属于 O(n) 的活；而状态栏的刷新触发点比消息变更频繁得多（权限模式、vim 模式、模型都会触发）。按 id 判断等于给它加了一层记忆。'''),
    (210, 'before', '''真正跑子进程。`logResult` 只在首跑或设置热重载后为真——因为执行命令会把完整快照写进调试日志，若每次都打，一次会话里几百条几乎相同的 JSON 会把日志淹掉。'''),
    (212, 'before', '''回写前先比一次值：`if (prev.statusLineText === text) return prev`。返回同一个对象引用，React 会直接跳过这次更新。这对状态栏尤其重要——它每 300ms 防抖后都可能返回**一模一样的文本**（比如显示的是分支名，没切分支），不比较就会白白重渲染整条底栏。'''),
    (226, 'before', '''防抖 300ms，且把 `debounceTimerRef` 与 `doUpdate` 一起传给 setTimeout 作为额外参数。这个写法有点绕（正常是闭包里直接用），好处是 `scheduleUpdate` 的依赖数组里可以只写 `doUpdate`，不必引用 timer ref——少一个依赖就少一次重建。'''),
    (237, 'before', '''触发条件写成一个显式的四元比较：消息 id、权限模式、vim 模式、模型。**没有**把 cwd、目录列表、设置对象放进来，因为那些变动不频繁、且大多伴随上面四项之一变化。注释里还特别说明「不要在这里更新 messageId」——留给 doUpdate 更新，才能保证 exceeds200k 用的是最新消息重算的。'''),
    (251, 'before', '''设置热重载：当 statusLine.command 变了（用户改了配置），强制下一次打日志并立刻刷新。第一次渲染要跳过（`isFirstSettingsRender`），否则挂载瞬间会多跑一次子进程——而挂载时的刷新已经在下面那个 effect 里做了。'''),
    (277, 'before', '''这段是「静默失败」的补丁。`executeStatusLineCommand` 在**工作区信任未被接受**时返回 undefined，于是 statusLineText 永远是 undefined、用户什么都看不到；而上面的 mount 遥测照样上报，从数据上看一切正常。所以这里额外查一次信任状态并弹一条低优先级通知，把「什么都没有」变成「有一行提示」。'''),
    (313, 'before', '''全屏模式下即使还没有文本也要渲染一个空格占位。原因写在注释里：底部是 `flexShrink: 0`，若命令跑完那一刻高度从 0 变 1，就会从滚动区抢走一行、内容整体上跳。预留一行是终端布局里对付「异步内容改变高度」的通用手法。'''),
    (323, 'before', '''最后用 memo 包一层。注释给了量化依据：父级 PromptInputFooter 每次 setMessages 都重渲染，而状态栏自己的 props 只在 lastAssistantMessageId 变化时才变——历史上一次会话里约有 18 次「props 没变却被拖着重渲染」。这一层 memo 就是把这 18 次挡掉的。'''),
]
